"use client";
/* Weather, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Weather(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("weather"); }, []);
  return React.createElement("piix-weather", piixAttrs(props));
}

export default Weather;
